def index(self, key):
    """ Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    # First try the built‑in index method (if the object inherits from a sequence)
    try:
        return super().index(key)
    except AttributeError:
        # Fall back to manual search
        for idx, item in enumerate(self):
            if item == key:
                return idx
    # If we get here the key was not found
    raise ValueError(f"{key!r} is not in container")

def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # Grab all items once to preserve order and allow index-based access
    try:
        items = list(self.items())
    except AttributeError:
        # Fallback: try to use dictionary-like item access
        items = list(self.__dict__.items())

    if not keys:
        # Return all values in order
        return [value for _, value in items]

    result = []
    for key in keys:
        if isinstance(key, int):
            # Index-based, allow negative indexing
            try:
                result.append(items[key][1])
            except Exception:
                pass
        else:
            # Key-based lookup
            try:
                result.append(self[key])
            except Exception:
                pass
    return result

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    # Prepare the attributes dictionary for the new class
    class_attrs = {}

    # Default None for each field so they become attributes of the instances
    for field in fields:
        class_attrs[field] = None

    # Store the srid map as a class attribute for potential future use
    class_attrs['_srid_map'] = srid_map

    # Define an __init__ that accepts coordinates, optional srid, and field values
    def __init__(self, x=0.0, y=0.0, srid=None, **kwargs):
        # Initialize the base Point (assuming Point supports x, y init)
        super(self.__class__, self).__init__(x, y)
        # Store srid if provided (adding an attribute dynamically)
        if srid is not None:
            self.srid = srid
        # Set any passed field values, otherwise keep defaults
        for f in fields:
            if f in kwargs:
                setattr(self, f, kwargs[f])

    class_attrs['__init__'] = __init__

    # Return a new type that inherits from Point
    return type(name, (Point,), class_attrs)

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    parts = s.split('.')
    result = []
    for part in parts:
        num_str = ''
        for ch in part:
            if ch.isdigit():
                num_str += ch
            else:
                break
        result.append(int(num_str) if num_str else 0)
    return tuple(result)

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.
    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            cache_key = key(*args, **kwargs)
            if lock:
                lock.acquire()
                try:
                    if cache_key in cache:
                        return cache[cache_key]
                    result = func(*args, **kwargs)
                    cache[cache_key] = result
                    return result
                finally:
                    lock.release()
            else:
                if cache_key in cache:
                    return cache[cache_key]
                result = func(*args, **kwargs)
                cache[cache_key] = result
                return result
        return wrapper
    return decorator

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    def decorator(func):
        cache = {}
        access_order = []

        def make_key(args, kwargs):
            if kwargs:
                items = tuple(sorted(kwargs.items()))
            else:
                items = ()
            if typed:
                key_args = args + tuple(type(v) for v in args)
            else:
                key_args = args
            return key_args + items

        def wrapper(*args, **kwargs):
            key = make_key(args, kwargs)
            now = timer()
            # Remove expired and update LRU order
            if key in cache:
                val, expire, _ = cache[key]
                if now >= expire:
                    # expired, remove
                    cache.pop(key)
                    access_order.remove(key)
                else:
                    # refresh order
                    try:
                        access_order.remove(key)
                    except ValueError:
                        pass
                    access_order.append(key)
                    return val

            if key in cache:
                # shouldn't happen because we just cleaned above
                try:
                    access_order.remove(key)
                except ValueError:
                    pass
                access_order.append(key)
                return cache[key][0]

            # Compute value
            result = func(*args, **kwargs)
            # Add to cache
            if len(cache) >= maxsize:
                # evict least recently used
                lru_key = access_order.pop(0)
                cache.pop(lru_key, None)
            expire_time = now + ttl
            cache[key] = (result, expire_time, now)
            access_order.append(key)
            return result

        return wrapper
    return decorator

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    def decorating_function(user_function):
        cache = {}

        def wrapper(*args, **kwargs):
            # Create a deterministic key
            if typed:
                key = (
                    args,
                    tuple(sorted(kwargs.items())),
                    tuple(type(v) for v in args),
                    tuple(type(v) for v in kwargs.values())
                )
            else:
                key = (
                    args,
                    tuple(sorted(kwargs.items()))
                )

            if key in cache:
                result, freq = cache[key]
                cache[key] = (result, freq + 1)
                return result

            result = user_function(*args, **kwargs)

            if maxsize and len(cache) >= maxsize:
                # Find the key with the lowest frequency
                min_freq = None
                key_to_remove = None
                for k, (_, f) in cache.items():
                    if min_freq is None or f < min_freq:
                        min_freq = f
                        key_to_remove = k
                if key_to_remove is not None:
                    del cache[key_to_remove]

            cache[key] = (result, 1)
            return result

        return wrapper

    return decorating_function

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    try:
        # Retrieve the first key in the dictionary's iteration order
        first_key = next(iter(self))
    except StopIteration:
        raise KeyError('dictionary is empty')
    # Pop the key to get the corresponding value
    value = self.pop(first_key)
    return first_key, value

def get(self, key, default=None):
    """
    D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None.
    """
