        return self[key]
    except KeyError:
        return default

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    cls = self.__class__

    def _collect(c):
        names = []
        ann = getattr(c, "__annotations__", {})
        names.extend(ann.keys())
        for k, v in c.__dict__.items():
            if k.startswith("_"):
                continue
            if callable(v):
                continue
            names.append(k)
        return names

    if all:
        seen = set()
        unique = []
        for c in reversed(cls.__mro__):
            if c is object:
                continue
            for name in _collect(c):
                if name not in seen:
                    seen.add(name)
                    unique.append(name)
        return unique
    else:
        names = _collect(cls)
        seen = set()
        unique = []
        for name in names:
            if name not in seen:
                seen.add(name)
                unique.append(name)
        return unique

