def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    errors = []

    for key, value in labels.items():
        # Validate key
        if not isinstance(key, str):
            errors.append({str(key): 'expected string or bytes-like object'})
        else:
            if not KUBE_LABEL_KEY_REGEX.match(key):
                errors.append(
                    {key: f"Label key '{key}' does not match the regex "
                          f"'{KUBE_LABEL_KEY_REGEX.pattern}'"}
                )

        # Validate value(s)
        def _validate_val(v):
            if isinstance(v, list):
                for sv in v:
                    _validate_val(sv)
            else:
                if not isinstance(v, str):
                    errors.append({str(v): 'expected string or bytes-like object'})
                else:
                    if not KUBE_LABEL_VALUE_REGEX.match(v):
                        errors.append(
                            {v: f"Label value '{v}' does not match the regex "
                                f"'{KUBE_LABEL_VALUE_REGEX.pattern}'"}
                        )

        _validate_val(value)

    if errors:
        raise ValidationError(errors)

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Recursively generate a default observer_schema from a Kubernetes resource manifest.
    Non-dict/non-list values are replaced with None.
    When first_level is True, the identifying fields ('metadata.name' and 'metadata.namespace')
    are preserved from the original manifest.
    """
    result = {}
    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            # Recurse into nested dictionaries; only top level has first_level True
            nested = generate_default_observer_schema_dict(value, False)
            result[key] = nested
        elif isinstance(value, list):
            # Delegate list handling to the corresponding helper
            result[key] = generate_default_observer_schema_list(value)
        else:
            result[key] = None

    if first_level:
        # Preserve identifying metadata fields
        meta = manifest_dict.get("metadata", {})
        if isinstance(result.get("metadata"), dict):
            preserved = {}
            for field in ("name", "namespace"):
                if field in meta:
                    preserved[field] = meta[field]
            # Only keep the preserved fields; drop all others
            result["metadata"] = preserved
        else:
            # If metadata wasn't a dict, recreate it with preserved fields
            preserved = {}
            for field in ("name", "namespace"):
                if field in meta:
                    preserved[field] = meta[field]
            if preserved:
                result["metadata"] = preserved
    return result

def validate(self, path):
    """
    Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        # Convert to Path-like object
        try:
            # If path is already a Path, keep it
            from pathlib import Path
            p = Path(path)
        except Exception:
            # Fallback: treat as string path
            p = path  # assume it is a string path
        if not hasattr(p, 'is_dir') or not p.is_dir():
            return False

        required_files = {"manifest.json", "layout.json", "object.json"}
        present_files = set()
        for entry in p.iterdir():
            if entry.is_file():
                present_files.add(entry.name)

        if not required_files.issubset(present_files):
            return False

        # Quickly check each file can be opened
        for filename in present_files:
            file_path = p / filename
            try:
                with file_path.open('rb') as fh:
                    fh.read(1)
            except Exception:
                return False

        return True
    except Exception:
        return False

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    # Determine the appropriate log source. It may be stored in an attribute named
    # ``validation_log`` or ``log``.  If neither exists, return a placeholder.
    log = getattr(self, 'validation_log', None)
    if log is None:
        log = getattr(self, 'log', None)

    if not isinstance(log, (list, tuple)):
        return f"{prefix}<no log>"

    # Build a string representation of each log entry, prefixing each line if
    # a prefix string was supplied.  The resulting lines are joined with newline
    # characters so the method returns a single multiline string.
    return "\n".join(prefix + str(entry) for entry in log)

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """

    # inventory must be a mapping
    if not isinstance(inventory, dict):
        raise ValueError("inventory must be a dictionary")

    # Determine spec version
    if extract_spec_version:
        inv_type = inventory.get("type")
        # If the inventory has a recognised type, use it as the spec version
        if inv_type and inv_type in getattr(self, "schemas", {}):
            self.spec_version = inv_type

    # Fetch the schema for the current spec version
    schema = getattr(self, "schemas", {}).get(self.spec_version)
    if schema is None:
        raise ValueError(f"Unsupported or missing spec version: {self.spec_version}")

    # Basic required field checks
    required = schema.get("required", [])
    for field in required:
        if field not in inventory:
            raise ValueError(f"Missing required field: {field}")

    # Property type checks
    properties = schema.get("properties", {})
    for field, rules in properties.items():
        if field in inventory:
            expected = rules.get("type")
            if expected:
                value = inventory[field]
                if expected == "string" and not isinstance(value, str):
                    raise ValueError(f"Field '{field}' expected to be string")
                if expected == "integer" and not isinstance(value, int):
                    raise ValueError(f"Field '{field}' expected to be integer")
                if expected == "boolean" and not isinstance(value, bool):
                    raise ValueError(f"Field '{field}' expected to be boolean")
                if expected == "object" and not isinstance(value, dict):
                    raise ValueError(f"Field '{field}' expected to be object")
                # Add other type checks if needed

    # If all checks pass, store validated inventory
    self.inventory = inventory
    return True

def check_digests_present_and_used(self, manifest_files, digests_used):
        """Check all digests in manifest that are needed are present and used."""
        # Normalize manifest digests into a set
        present_digests = set()
        for mf in manifest_files:
            if hasattr(mf, 'digest'):
                dig = mf.digest
            elif isinstance(mf, dict) and 'digest' in mf:
                dig = mf['digest']
            else:
                raise ValueError("Manifest entry must have a 'digest' attribute or key")
            present_digests.add(dig)

        # Normalize used digests into a set
        used_digests = set(digests_used)

        # Digests expected to be present but missing in the manifest
        missing = used_digests - present_digests
        if missing:
            raise ValueError(f"Missing digests in manifest: {sorted(missing)}")

        # Digests present in the manifest but unused
        unused = present_digests - used_digests
        if unused:
            raise ValueError(f"Unused digests present in manifest: {sorted(unused)}")
        return True

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Ensure prior is the same type as self
    if not isinstance(prior, type(self)):
        raise TypeError(
            f"Expected 'prior' to be an instance of {type(self).__name__}, "
            f"got {type(prior).__name__}"
        )

    # The objects are assumed internally consistent, so we only need to
    # validate that prior represents an older version of the inventory.

    # 1. Check that both objects expose a version attribute.
    if not hasattr(self, "inventory_version") or not hasattr(prior, "inventory_version"):
        raise AttributeError(
            "Both inventory objects must have an 'inventory_version' attribute"
        )
    self_ver = getattr(self, "inventory_version")
    prior_ver = getattr(prior, "inventory_version")

    # 2. Ensure the types of the versions are comparable (prefer ints or floats)
    if not isinstance(self_ver, (int, float)) or not isinstance(prior_ver, (int, float)):
        raise TypeError("'inventory_version' must be an int or float")

    # 3. Validate that prior is indeed older (strictly less)
    if prior_ver >= self_ver:
        raise ValueError(
            f"'prior.inventory_version' ({prior_ver}) must be less than "
            f"current 'inventory_version' ({self_ver})"
        )

    # 4. (Optional) Compare timestamps if available
    if hasattr(self, "timestamp") and hasattr(prior, "timestamp"):
        self_ts = getattr(self, "timestamp")
        prior_ts = getattr(prior, "timestamp")

        # Support datetime or numeric timestamps but avoid importing datetime
        if isinstance(self_ts, (int, float)) and isinstance(prior_ts, (int, float)):
            if prior_ts >= self_ts:
                raise ValueError(
                    f"'prior.timestamp' ({prior_ts}) must be earlier than "
                    f"current 'timestamp' ({self_ts})"
                )
        elif isinstance(self_ts, object) and isinstance(prior_ts, object):
            # If they are datetime-like, attempt comparison
            try:
                if prior_ts >= self_ts:
                    raise ValueError(
                        f"'prior.timestamp' ({prior_ts}) must be earlier than "
                        f"current 'timestamp' ({self_ts})"
                    )
            except Exception:
                # If comparison fails, ignore silently
                pass

    # 5. Ensure inventory types match
    inventory_type_self = getattr(self, "inventory_type", None)
    inventory_type_prior = getattr(prior, "inventory_type", None)
    if inventory_type_self is not None and inventory_type_prior is not None:
        if inventory_type_self != inventory_type_prior:
            raise ValueError(
                f"Inventory type mismatch: {inventory_type_self} != {inventory_type_prior}"
            )

def get_logical_path_map(inventory, version):
    """
    Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    result = {}
    # Determine how the inventory is structured. It may be a mapping from version
    # to data or a list of records containing versions.
    data = None

    # If inventory is a mapping from version to something
    if isinstance(inventory, dict):
        data = inventory.get(version)
    # If inventory itself is a list of records with a 'version' key
    if data is None and isinstance(inventory, list):
        data = [rec for rec in inventory if rec.get('version') == version]
    # If still None, nothing found – return empty dict
    if data is None:
        return result

    # Helper: add a content file to a logical path in the result
    def add_to_result(lp, cf):
        if lp not in result:
            result[lp] = set()
        result[lp].add(cf)

    # Now interpret the data structure
    if isinstance(data, dict):
        # Expect mapping from logical_path -> list/set/tuple of content files
        for lp, files in data.items():
            if isinstance(files, (list, set, tuple)):
                result[lp] = set(files)
            else:
                result[lp] = {files}
    elif isinstance(data, list):
        # Iterate over records
        for entry in data:
            if isinstance(entry, (list, tuple)) and len(entry) >= 2:
                lp, cf = entry[0], entry[1]
                add_to_result(lp, cf)
            elif isinstance(entry, dict):
                lp = entry.get('logical_path')
                cf = entry.get('content_file')
                if lp is not None and cf is not None:
                    add_to_result(lp, cf)
    # If data is a single record (tuple or dict)
    elif isinstance(data, (list, tuple)) and len(data) >= 2:
        add_to_result(data[0], data[1])
    elif isinstance(data, dict) and 'logical_path' in data and 'content_file' in data:
        add_to_result(data['logical_path'], data['content_file'])

    return result

def fix_namespace_prefix_w(content):
    """
    Convert os textos cujo padrão é `w:st="` em `w-st="`.
    """
    return content.replace('w:st="', 'w-st="')

def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    for xpath in pubdate_xpaths:
        try:
            matches = node.xpath(xpath)
        except Exception:
            # Se o XPath falhar, simplesmente salta para o próximo
            continue

        for match in matches:
            # Se o resultado já for uma string, devolve essa string
            if isinstance(match, str):
                return match.strip()

            # Se o resultado for um elemento XML/HTML, tenta extrair o texto
            if hasattr(match, "text"):
                return match.text.strip()

            # Algumas bibliotecas retornam objetos com text_content()
            if hasattr(match, "text_content"):
                return match.text_content().strip()

    # Se nenhum dos XPath correspondesse, devolve None
    return None

