                return o.pretty(indent=level, debug=debug)
            if isinstance(o, dict):
                lines = []
                for k, v in sorted(o.items()):
                    lines.append(f"{prefix}{k}:")
                    lines.append(_format(v, level + 2))
                return "\n".join(lines)
            if isinstance(o, (list, tuple, set)):
                lines = []
                for item in o:
                    lines.append(_format(item, level + 2))
                return "\n".join(lines)
            return prefix + repr(o)

        representation = _format(self, indent)
        if debug:
            return f"{self.__class__.__name__} at {hex(id(self))}:\n" + representation
        return representation

def get_versions():
    """Get version information or return default if unable to do so."""
    import sys
    versions = {}
    # Python interpreter version
    try:
        versions["python"] = sys.version.split()[0]
    except Exception:
        versions["python"] = None

    # NumPy version
    try:
        import numpy as np
        versions["numpy"] = np.__version__
    except Exception:
        versions["numpy"] = None

    # pandas version
    try:
        import pandas as pd
        versions["pandas"] = pd.__version__
    except Exception:
        versions["pandas"] = None

    # Site-packages directory (if available)
    try:
        import site
        sites = site.getsitepackages()
        versions["site-packages"] = sites[0] if sites else None
    except Exception:
        versions["site-packages"] = None

    return versions

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    return '+' if '+' not in pieces else '.'

def register_vcs_handler(vcs, method=None):
    """Create decorator to mark a method as the handler of a VCS.

    The function can be used as a decorator factory::

        @register_vcs_handler('git')
        def handler(...):
            ...

    After registration, the handler can be accessed via::

        register_vcs_handler.handlers['git']

    Returns:
        The original method unmodified.
    """
    if method is None:
        def decorator(func):
            if not hasattr(register_vcs_handler, "handlers"):
                register_vcs_handler.handlers = {}
            register_vcs_handler.handlers[vcs] = func
            return func
        return decorator
    else:
        if not hasattr(register_vcs_handler, "handlers"):
            register_vcs_handler.handlers = {}
        register_vcs_handler.handlers[vcs] = method
        return method

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Determine iterable collection of objects in the hierarchy.
    objects = getattr(self, 'objects', None)
    if objects is None:
        objects = getattr(self, 'children', None)
    if objects is None:
        # If the object itself is iterable, use it directly.
        if hasattr(self, '__iter__'):
            objects = self
        else:
            # No objects found; nothing to validate.
            return 0, 0

    num_objects = 0
    good_objects = 0

    for obj in objects:
        num_objects += 1
        is_valid = True

        # Validate the object itself if requested.
        if validate_objects:
            try:
                if hasattr(obj, 'validate'):
                    is_valid = obj.validate()
                else:
                    # Default to True if no validate method is available.
                    is_valid = True
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    print(f"Warning: validation failed for object {obj}: {exc}")

        # Check the digest of the object if requested.
        if is_valid and check_digests:
            try:
                if hasattr(obj, 'check_digest'):
                    obj.check_digest()
                # If the method doesn't exist, we assume it is fine.
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    print(f"Warning: digest check failed for object {obj}: {exc}")

        if is_valid:
            good_objects += 1
        else:
            if show_warnings:
                print(f"Warning: object {obj} is invalid.")

    return num_objects, good_objects

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        raise TypeError("version must be a string")
    version = version.strip()
    if not version:
        return "1"
    parts = version.split('.')
    last = parts[-1]
    if not last.isdigit():
        # if the last part isn't purely numeric, just append .1
        return version + ".1"
    width = len(last)
    new_num = int(last) + 1
    if last.startswith('0'):
        parts[-1] = str(new_num).zfill(width)
    else:
        parts[-1] = str(new_num)
    return '.'.join(parts)

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    import os, json

    # Load the root inventory which is expected to live in the current working directory.
    root_inventory_path = os.path.join(os.getcwd(), "root_inventory.json")
    if not os.path.isfile(root_inventory_path):
        raise FileNotFoundError(f"Root inventory file not found: {root_inventory_path}")

    with open(root_inventory_path, "r", encoding="utf-8") as f:
        root_inventory = json.load(f)

    # This will hold any digest mismatches found between a version's inventory
    # and the root inventory.  Format:
    # { filename: [ {version: ..., root_digest: ..., current_digest: ...}, ... ] }
    differing_digests = {}

    for ver_dir in version_dirs:
        inv_path = os.path.join(ver_dir, "inventory.json")
        if not os.path.isfile(inv_path):
            raise FileNotFoundError(f"Inventory file missing in {ver_dir}")

        with open(inv_path, "r", encoding="utf-8") as f:
            inv = json.load(f)

        # Ensure the inventory for this version contains all files that appear
        # in the root inventory up to this point.
        for filename, root_digest in root_inventory.items():
            if filename not in inv:
                raise AssertionError(
                    f"File '{filename}' missing from inventory in {ver_dir}"
                )
            current_digest = inv[filename]
            if current_digest != root_digest:
                differing_digests.setdefault(filename, []).append(
                    {
                        "version": ver_dir,
                        "root_digest": root_digest,
                        "current_digest": current_digest,
                    }
                )

    # Store the differences on the instance for later validation checks.
    self.differing_digests = differing_digests
    return differing_digests

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params to include the given bug IDs."""
    if bug_ids is None:
        return params

    # Ensure bug_ids is an iterable of integers or strings that can be cast to int
    try:
        bug_ids_list = list(bug_ids)
    except TypeError:  # bug_ids is a single value
        bug_ids_list = [bug_ids]

    # Normalise existing ids in params (if any)
    existing = params.get('ids')
    if existing:
        if isinstance(existing, str):
            existing_ids = [int(x) for x in existing.split(',') if x]
        else:
            existing_ids = list(existing)
        all_ids = set(existing_ids) | set(bug_ids_list)
    else:
        all_ids = set(bug_ids_list)

    if all_ids:
        # Store as a comma‑separated string, sorted for consistency
        params['ids'] = ','.join(map(str, sorted(all_ids)))
    else:
        # Remove ids key if there are no ids left
        params.pop('ids', None)

    return params

def deep_merge_nodes(nodes):
    """
    Deep merge a list of YAML nodes, where each node is a tuple
    (ScalarNode key, MappingNode|any value). Duplicate keys are
    merged recursively if the values are MappingNodes; otherwise
    the value from the later node wins.

    The function assumes that `ruamel.yaml.nodes.ScalarNode` and
    `ruamel.yaml.nodes.MappingNode` are available in the
    runtime environment.
    """
    from ruamel.yaml.nodes import MappingNode

    def merge_mapping_nodes(m1, m2):
        """Merge two MappingNodes and return a new MappingNode."""
        merged_items = deep_merge_items(m1.value + m2.value)
        return MappingNode(tag=m1.tag, value=merged_items)

    def deep_merge_values(v1, v2):
        """Merge two values when a conflict occurs."""
        if isinstance(v1, MappingNode) and isinstance(v2, MappingNode):
            return merge_mapping_nodes(v1, v2)
        # For non-mapping values, the later value overwrites the earlier one.
        return v2

    def deep_merge_items(items):
        """Process a list of (key_node, value_node) tuples."""
        result = []
        key_index = {}

        for key_node, value_node in items:
            key = key_node.value
            if key not in key_index:
                key_index[key] = len(result)
                result.append((key_node, value_node))
            else:
                idx = key_index[key]
                existing_key, existing_value = result[idx]
                merged_value = deep_merge_values(existing_value, value_node)
                result[idx] = (existing_key, merged_value)
        return result

    return deep_merge_items(list(nodes))

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    flags = []
    for action in parser._actions:
        # Skip actions that do not have option strings (e.g., positional or internal)
        if action.option_strings:
            flags.extend(action.option_strings)
    return ' '.join(flags)

def deep_merge_nodes(nodes):
    """
    Deep merge a list of (key_node, value_node) tuples where key_node is a ScalarNode
    and value_node is either a MappingNode or any other ScalarNode. Duplicate keys
    are merged recursively; if values are non-mapping nodes, the last one wins.
    """
    # Helper to merge two value nodes
    def merge_values(a, b):
        if isinstance(a, ruamel.yaml.nodes.MappingNode) and isinstance(b, ruamel.yaml.nodes.MappingNode):
            # Build dict from a
            a_dict = {}
            for k, v in a.value:
                a_dict[k.value] = (k, v)
            # Merge b into a_dict
            for k, v in b.value:
                if k.value in a_dict:
                    hk, hv = a_dict[k.value]
                    merged_v = merge_values(hv, v)
                    a_dict[k.value] = (hk, merged_v)
                else:
                    a_dict[k.value] = (k, v)
            # Preserve insertion order: start with a's keys then appended new ones
            result = []
            seen = set()
            for k, v in a.value:
                result.append((k, a_dict[k.value][1]))
                seen.add(k.value)
            for k in b.value:
                if k.value not in seen:
                    result.append(a_dict[k.value])
            return ruamel.yaml.nodes.MappingNode(a.tag, result)
        else:
            # Non-mapping: last wins
            return b

    # Maintain final list and map of key values to their index
    final_list = []
    key_index = {}
    for key_node, val_node in nodes:
        key_val = key_node.value
        if key_val in key_index:
            idx = key_index[key_val]
            existing_key, existing_val = final_list[idx]
            merged_val = merge_values(existing_val, val_node)
            final_list[idx] = (existing_key, merged_val)
        else:
            key_index[key_val] = len(final_list)
            final_list.append((key_node, val_node))
    return final_list

