def parse_subparser_arguments(unparsed_arguments, subparsers):
    """
    Give each subparser (if any) a chance to parse all arguments, allowing for common
    arguments such as "--repository".  Each subparser gets its own namespace.  The
    function returns a tuple:
        (dict mapping subparser name -> parsed namespace,
         list of arguments that none of the subparsers recognized)
    """
    parsed = {}
    remaining_lists = []

    for name, parser in subparsers.items():
        ns, rem = parser.parse_known_args(unparsed_arguments)
        parsed[name] = ns
        remaining_lists.append(rem)

    # Arguments unseen by every subparser:
    if remaining_lists:
        unknown_set = set(remaining_lists[0])
        for rem in remaining_lists[1:]:
            unknown_set &= set(rem)
    else:
        unknown_set = set()

    remaining = [arg for arg in unparsed_arguments if arg in unknown_set]
    return parsed, remaining

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    result = {}
    for d in dicts:
        for key, value in d.items():
            result[key] = result.get(key, 0) + value
    return result

