def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None:
        return None
    freq_str = frequency.strip()
    if freq_str.lower() == 'always':
        return None
    import re
    match = re.match(r'^\s*(\d+(?:\.\d+)?)\s*([a-zA-Z]+)\s*$', freq_str)
    if not match:
        raise ValueError(f"Could not parse frequency: {frequency!r}")
    value_str, unit = match.group(1), match.group(2).lower()
    try:
        value = float(value_str) if '.' in value_str else int(value_str)
    except ValueError:
        raise ValueError(f"Invalid numeric value in frequency: {value_str!r}")
    unit_map = {
        'day': 'days', 'days': 'days',
        'week': 'weeks', 'weeks': 'weeks',
        'hour': 'hours', 'hours': 'hours',
        'minute': 'minutes', 'minutes': 'minutes',
        'second': 'seconds', 'seconds': 'seconds',
    }
    if unit not in unit_map:
        raise ValueError(f"Unsupported time unit in frequency: {unit!r}")
    kwargs = {unit_map[unit]: value}
    return datetime.timedelta(**kwargs)

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not host or not isinstance(host, str):
        return False

    # Strip whitespace and lower-case for simple comparison
    host_clean = host.strip().lower()

    # Direct matches for common localhost identifiers
    if host_clean in {"localhost", "127.0.0.1", "::1"}:
        return True

    # Attempt to resolve the host to IP addresses and check for loopback addresses
    try:
        import socket
        try:
            # Use getaddrinfo to retrieve IPv4 and IPv6 addresses
            infos = socket.getaddrinfo(host_clean, None, proto=socket.IPPROTO_TCP)
        except socket.gaierror:
            return False

        for addr in infos:
            ip = addr[4][0]
            # IPv4 loopback
            if ip == "127.0.0.1":
                return True
            # IPv6 loopback
            if ip == "::1":
                return True
            # Handle IPv4-mapped IPv6 addresses
            if ip.startswith("::ffff:127.0.0.1"):
                return True

        return False
    except Exception:
        return False"""}

