def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    # Dump the object to a YAML string using the optional custom Dumper.
    yaml_output = yaml.safe_dump(
        obj,
        default_flow_style=False,
        allow_unicode=True,
        Dumper=dumper,
    )
    # On Python 2, yaml.safe_dump returns a byte string; convert it to unicode.
    if isinstance(yaml_output, bytes):
        try:
            return yaml_output.decode("utf-8")
        except Exception:
            return yaml_output.decode("latin-1")
    # On Python 3, the output is already a str (unicode).
    return yaml_output

def gaussian(x):
    """Gaussian centered around 0.2 with a sigma of 0.1."""
    return np.exp(-((x - 0.2) ** 2) / (2 * 0.1 ** 2))

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    import json, configparser, logging, os, re
    try:
        import yaml
        _yaml_available = True
    except ImportError:
        _yaml_available = False

    config_results = {}
    error_records = []
    logger_name = __name__
    for filename in config_filenames:
        config_data = None
        try:
            with open(filename, 'r', encoding='utf-8') as f:
                ext = os.path.splitext(filename)[1].lower()
                if ext == '.json':
                    config_data = json.load(f)
                elif ext in ('.yaml', '.yml'):
                    if not _yaml_available:
                        raise RuntimeError('PyYAML is required for YAML files')
                    config_data = yaml.safe_load(f)
                elif ext in ('.ini', '.cfg'):
                    parser = configparser.ConfigParser()
                    parser.read_file(f)
                    config_data = {s: dict(parser.items(s)) for s in parser.sections()}
                else:
                    raise RuntimeError(f'Unsupported file extension: {ext}')
            if config_data is None:
                config_data = {}
        except Exception as exc:
            # Build a LogRecord for the error
            record = logging.LogRecord(
                name=logger_name,
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f'Error loading configuration file {filename}: {exc}',
                args=(),
                exc_info=exc
            )
            error_records.append(record)
            config_results[filename] = None
            continue

        # Resolve environment variables in string values
        def _replace_env(val):
            if isinstance(val, str):
                return os.path.expandvars(val)
            elif isinstance(val, dict):
                return {k: _replace_env(v) for k, v in val.items()}
            elif isinstance(val, list):
                return [_replace_env(v) for v in val]
            else:
                return val

        if resolve_env:
            try:
                config_data = _replace_env(config_data)
            except Exception as exc:
                record = logging.LogRecord(
                    name=logger_name,
                    level=logging.ERROR,
                    pathname=filename,
                    lineno=0,
                    msg=f'Error resolving environment variables in {filename}: {exc}',
                    args=(),
                    exc_info=exc
                )
                error_records.append(record)

        # Apply overrides (top‑level merge)
        if overrides and isinstance(overrides, dict):
            try:
                config_data.update(overrides)
            except Exception as exc:
                record = logging.LogRecord(
                    name=logger_name,
                    level=logging.ERROR,
                    pathname=filename,
                    lineno=0,
                    msg=f'Error applying overrides to {filename}: {exc}',
                    args=(),
                    exc_info=exc
                )
                error_records.append(record)

        config_results[filename] = config_data

    return (config_results, error_records)

def force_string(obj):
    """Return a UTF-8 encoded bytes object if ``obj`` is a string; otherwise return ``obj`` unchanged."""
    if isinstance(obj, str):
        return obj.encode('utf-8')
    return obj

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                   field_names=("x", "y"), scale=None):
    """Convert a histogram to a graph representation.

    The histogram object is expected to provide an iterable of bin objects
    accessible through ``hist.bins``.  Each bin should expose at least the
    attributes ``left``, ``right`` and ``content`` (or ``value`` if ``content``
    is not present).  ``make_value`` transforms the bin content into a tuple
    of graph y-values.  The function returns a list of tuples, one for each
    bin, where the first element is the x‑coordinate (determined by
    ``get_coordinate``) and the following elements are the y‑components.
    """
    if get_coordinate not in ("left", "right", "middle"):
        raise ValueError(
            f"Invalid get_coordinate: {get_coordinate!r}. "
            "Expected one of 'left', 'right' or 'middle'."
        )

    result = []

    for bin_obj in getattr(hist, "bins", []):
        # Find the bin coordinate
        left = getattr(bin_obj, "left", None)
        right = getattr(bin_obj, "right", None)
        if left is None or right is None:
            # Cannot determine coordinate; skip this bin
            continue

        if get_coordinate == "left":
            coord = left
        elif get_coordinate == "right":
            coord = right
        else:
            coord = (left + right) / 2

        # Determine the y-values
        if make_value is None:
            y_val = getattr(bin_obj, "content", None)
            if y_val is None:
                y_val = getattr(bin_obj, "value", None)
            if y_val is None:
                raise ValueError(
                    "Histogram bin does not provide a numeric value."
                )
            point = (coord, y_val)
        else:
            # make_value only receives the numeric content
            y_val = getattr(bin_obj, "content", None)
            if y_val is None:
                y_val = getattr(bin_obj, "value", None)
                if y_val is None:
                    raise ValueError(
                        "Histogram bin does not provide a numeric value."
                    )
            y_vals = make_value(y_val)
            if not isinstance(y_vals, (list, tuple)):
                raise ValueError(
                    "make_value must return an iterable of values."
                )
            if len(y_vals) != len(field_names) - 1:
                raise ValueError(
                    "make_value returned the wrong number of values. "
                    f"Expected {len(field_names)-1}, got {len(y_vals)}."
                )
            point = (coord,) + tuple(y_vals)

        result.append(point)

    # The optional ``scale`` argument is ignored in this general implementation.
    # If the caller wants to propagate a scale attribute they can handle that
    # after receiving the list of points.
    return result

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    # `iface` must be a class or interface (i.e., a type).
    if not isinstance(iface, type):
        raise TypeError("iface must be a class or interface type")

    # Determine if candidate is a class or an instance.
    candidate_is_class = isinstance(candidate, type)

    # Basic checks: subclass or instance.
    if not tentative:
        if candidate_is_class:
            if not issubclass(candidate, iface):
                raise TypeError(f"{candidate!r} does not subclass {iface!r}")
        else:
            if not isinstance(candidate, iface):
                raise TypeError(f"{candidate!r} is not an instance of {iface!r}")

    # If tentative, perform a relaxed check that the candidate
    # provides the attributes/methods defined by `iface`.
    if tentative:
        # Iterate over public attributes of the interface.
        for name in dir(iface):
            # Skip special/magic attributes.
            if name.startswith("__") and name.endswith("__"):
                continue
            iface_attr = getattr(iface, name)
            # If the interface attribute is callable, ensure candidate has a callable
            if callable(iface_attr):
                if not hasattr(candidate, name) or not callable(getattr(candidate, name)):
                    raise TypeError(f"{candidate!r} lacks method '{name}' required by {iface!r}")
    return True

def pop(self, key, default=__marker):
    if key in self:
        value = self[key]
        del self[key]
        return value
    if default is __marker:
        raise KeyError(key)
    return default

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    if not hasattr(self, 'cache') or not self.cache:
        raise KeyError('popitem(): dictionary is empty')
    return self.cache.popitem(last=False)

def popitem(self):
    """Remove and return a random `(key, value)` pair."""
    return super().popitem()

def _create_converter(self) -> _converting._Converter:
    """
    Create the parameter style converter.

    Returns the parameter style converter (:class:`._converting._Converter`).
    """
    return _converting._Converter()

def default_tzinfo(dt, tzinfo):
    """
    Sets the ``tzinfo`` parameter on naive datetimes only.

    :param dt: datetime.datetime
    :param tzinfo: datetime.tzinfo instance
    :return: datatime.datetime
    """
    # If the datetime is naive (no tzinfo or tzinfo.utcoffset is None), replace tzinfo.
    try:
        tz_offset = dt.tzinfo.utcoffset(dt)
    except Exception:
        tz_offset = None
    if dt.tzinfo is None or tz_offset is None:
        return dt.replace(tzinfo=tzinfo)
    return dt

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    # Heuristic approach: check for typical Matrix request attributes
    try:
        # 1. Some framework might store a type or category on the request
        if getattr(request, "type", None) == "matrix":
            return True
        # 2. Matrix endpoints usually start with '/_matrix'
        path = getattr(request, "path", None)
        if isinstance(path, str) and path.startswith("/_matrix"):
            return True
        # 3. Some request objects may expose a `request_type` attribute
        if getattr(request, "request_type", None) == "matrix":
            return True
        # 4. Fallback: look for a custom flag
        if getattr(request, "__matrix__", False):
            return True
    except Exception:
        # In case any attribute access fails, we consider it not a Matrix request
        pass
    return False

def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.
    """
    try:
        # Attempt to retrieve the header information using a HEAD request.
        response = requests.head(url, allow_redirects=True, timeout=5)
        # If the request succeeds, return the 'Content-Type' header if present.
        if response.status_code == 200:
            return response.headers.get('Content-Type')
    except Exception:
        # Any network or HTTP errors are silently ignored, resulting in None.
        pass
    # Return None if the request failed or the header is missing.
    return None

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    if not tag:
        return False
    for c in tag:
        if not (c.isalnum() or c == '-'):
            return False
    return True

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversion - child nodes are not recursively processed.
    """
    result = {}
    for child in node:
        tag = child.tag
        # strip namespace if present
        if '}' in tag:
            tag = tag.split('}', 1)[-1]
        if tag in result:
            # if already a list, simply append
            if isinstance(result[tag], list):
                result[tag].append(child)
            else:
                # convert existing entry to a list
                result[tag] = [result[tag], child]
        else:
            result[tag] = child
    return result

def check_sender_and_entity_handle_match(sender_handle, entity_handle):
    """Ensure that sender and entity handles match.

    Basically we've already verified the sender is who they say when receiving the payload. However, the sender might
    be trying to set another author in the payload itself, since Diaspora has the sender in both the payload headers
    AND the object. We must ensure they're the same.
    """
    if sender_handle != entity_handle:
        raise ValueError(
            f"Sender handle '{sender_handle}' does not match entity handle '{entity_handle}'."
        )

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json, xml.etree.ElementTree as ET

    # Try JSON first
    try:
        data = json.loads(document)
    except json.JSONDecodeError:
        # Assume XRD (XML)
        try:
            root = ET.fromstring(document)
        except ET.ParseError:
            return {}

        # Helper to strip namespace
        def _strip(t):
            return t[ t.find("}") + 1 :] if "}" in t else t

        subject = None
        aliases = []
        links = []

        # Get subject
        subject_elem = root.find('.//' + _strip("{*}Subject"))
        if subject_elem is not None and subject_elem.text:
            subject = subject_elem.text

        # Get aliases (in old Diaspora, aliases are in <Alias> tags)
        for alias_elem in root.findall('.//' + _strip("{*}Alias")):
            if alias_elem.text:
                aliases.append(alias_elem.text)

        # Get links
        for link_elem in root.findall('.//' + _strip("{*}Link")):
            rel = link_elem.attrib.get('rel')
            href = link_elem.attrib.get('href')
            type_attr = link_elem.attrib.get('type')
            if rel and href:
                links.append({'rel': rel, 'href': href, 'type': type_attr})
        # Return union dict
        return {'subject': subject, 'aliases': aliases, 'links': links}

    # JSON path
    subject = data.get('subject')
    aliases = data.get('aliases', [])
    links = []

    for link in data.get('links', []):
        rel = link.get('rel')
        href = link.get('href')
        type_attr = link.get('type')
        if rel and href:
            links.append({'rel': rel, 'href': href, 'type': type_attr})
    return {'subject': subject, 'aliases': aliases, 'links': links}

def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: parsed XML Element (XRD)
    """
    from urllib import request, error
    import xml.etree.ElementTree as ET

    # Normalize host to include scheme
    if "://" not in host:
        host = f"https://{host}"

    # Build the host-meta URL
    host_meta_url = host.rstrip("/") + "/.well-known/host-meta"

    # Function to fetch and parse the host-meta XML
    def fetch(url):
        try:
            with request.urlopen(url, timeout=10) as resp:
                data = resp.read()
            return ET.fromstring(data)
        except error.HTTPError as e:
            raise RuntimeError(f"HTTP error while retrieving host-meta: {e}") from e
        except error.URLError as e:
            raise RuntimeError(f"URL error while retrieving host-meta: {e}") from e
        except ET.ParseError as e:
            raise RuntimeError("Failed to parse host-meta XML") from e

    try:
        return fetch(host_meta_url)
    except RuntimeError:
        # Fallback to http if https fails
        if host.startswith("https://"):
            fallback_url = host_meta_url.replace("https://", "http://", 1)
            return fetch(fallback_url)
        raise

def list_of_file_names(settings_dirs, spec_option):
    """Return a sorted list of file names from the provided directories, optionally filtered by a pattern."""
    import os
    import fnmatch

    # Ensure settings_dirs is a list
    if isinstance(settings_dirs, str):
        dirs = [settings_dirs]
    else:
        dirs = list(settings_dirs)

    file_names = []
    for directory in dirs:
        if not os.path.isdir(directory):
            continue
        for entry in os.listdir(directory):
            full_path = os.path.join(directory, entry)
            if os.path.isfile(full_path):
                if spec_option is None or fnmatch.fnmatch(entry, spec_option):
                    file_names.append(entry)

    return sorted(file_names)

def workspace_manager(cls):
    """Gets the workspace manager. """
    if not hasattr(cls, "_workspace_manager"):
        # Lazy initialization of the workspace manager
        cls._workspace_manager = cls._WorkspaceManager()
    return cls._workspace_manager

def plugins_manager(cls):
        """Gets the plugin manager."""
        # Initialize a private class attribute if it does not exist
        if not hasattr(cls, "_plugin_manager"):
            cls._plugin_manager = {}
        return cls._plugin_manager

def validate_from_file(cls, yaml_file=None):
        """Loads & validates that a YAML file has all required fields

        :param yaml_file: Path to YAML file
        :raise IRValidatorException: when mandatory data is missing in file
        :return: Dictionary with data loaded from a YAML file
        """
        import yaml
        if not yaml_file:
            raise IRValidatorException("No YAML file path supplied")

        # Read the file contents
        try:
            with open(yaml_file, "r", encoding="utf-8") as fp:
                content = fp.read()
        except Exception as exc:
            raise IRValidatorException(f"Error reading YAML file '{yaml_file}': {exc}")

        # Parse YAML
        try:
            data = yaml.safe_load(content)
        except yaml.YAMLError as exc:
            raise IRValidatorException(f"Invalid YAML syntax in '{yaml_file}': {exc}")

        if data is None:
            raise IRValidatorException(f"YAML file '{yaml_file}' is empty or contains only comments")

        # Validate required fields
        missing = []
        # Assume the class defines a class attribute REQUIRED_FIELDS
        for key in getattr(cls, "REQUIRED_FIELDS", []):
            if key not in data:
                missing.append(key)

        if missing:
            missing_str = ", ".join(missing)
            raise IRValidatorException(
                f"YAML file '{yaml_file}' is missing required fields: {missing_str}"
            )

        return data

def _include_groups(self, parser_dict):
        """Resolves the include dict directive in the spec files."""
        # The include directive is expected to be a mapping of group names to
        # either a relative file path (string) or a nested dictionary of
        # items that should be merged into the current spec.
        includes = parser_dict.pop("include", {})
        if not isinstance(includes, dict):
            raise ValueError(
                f"The 'include' field must be a dictionary, got {type(includes).__name__}"
            )

        for group_name, include_source in includes.items():
            # If the include source is a string, treat it as a path to a
            # spec file and recursively parse it.
            if isinstance(include_source, str):
                try:
                    included_spec = self._parse_file(include_source)
                except Exception as exc:
                    raise ValueError(
                        f"Failed to load include file '{include_source}' for group '{group_name}': {exc}"
                    ) from exc
                # Nested includes are merged at the group level
                parser_dict[group_name] = included_spec
            # If the source is a dictionary, merge it into the group
            elif isinstance(include_source, dict):
                existing = parser_dict.get(group_name, {})
                if not isinstance(existing, dict):
                    raise ValueError(
                        f"Existing group '{group_name}' is not a dict; cannot merge with include dict."
                    )
                parser_dict[group_name] = self._merge_dicts(existing, include_source)
            else:
                raise TypeError(
                    f"Unsupported include type for group '{group_name}': "
                    f"{type(include_source).__name__}"
                )

        return parser_dict

def get_spec_defaults(self):
        """Resolve arguments' values from spec and other sources."""
        defaults = {}
        spec = getattr(self, "spec", {})
        # `spec` could be a dict mapping argument names to metadata
        if isinstance(spec, dict):
            for name, meta in spec.items():
                # Prefer an explicit default if present
                if isinstance(meta, dict):
                    if "default" in meta:
                        defaults[name] = meta["default"]
                    elif "value" in meta:
                        defaults[name] = meta["value"]
                else:
                    # If the spec entry is a direct value, use it
                    defaults[name] = meta
        else:
            # Fallback: if spec is not a dict, no defaults can be extracted
            pass
        return defaults

def get_deprecated_args(self):
    """Returning dict with options which deprecate others."""
    return {}

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    # Retrieve the set or dict of deprecated argument names.
    # It can be defined as a set/list/tuple or a dict mapping old to new names.
    deprecated = getattr(self, "deprecated_arguments", set())

    # Helper to extract just the keys if deprecated is a dict mapping old -> new.
    if isinstance(deprecated, dict):
        deprecated_set = set(deprecated.keys())
    else:
        deprecated_set = set(deprecated)

    # Check both sources for deprecated arguments.
    for src_name, args in [("CLI", cli_args), ("Answer File", answer_file_args)]:
        for key in args:
            if key in deprecated_set:
                print(f"WARNING: Argument '{key}' from {src_name} is deprecated.")

def get_silent_args(self, args):
        """list of silenced argument

        :param args: The received arguments.
        :return: list, slienced argument names
        """
        if args is None:
            return []

        silent_args = []

        # If args is a dict (common in simple parsers)
        if isinstance(args, dict):
            for key in args:
                if key.startswith("_"):
                    silent_args.append(key)

        # If args is an argparse.Namespace or similar
        else:
            # Many namespaces expose their data via __dict__ attribute
            try:
                data = vars(args)
            except TypeError:
                # If vars fails, fallback to empty list
                data = {}
            for key in data:
                if key.startswith("_"):
                    silent_args.append(key)

        return silent_args

def validate_length_args(self, args):
        """Check if value of arguments is not longer than length specified.

        :param args: The received arguments.
        """
        # If the instance has a 'lengths' mapping that specifies maximum
        # allowed lengths for each argument name, validate against it.
        lengths = getattr(self, "lengths", None)
        if not lengths:
            return

        for name, value in args.items():
            max_len = lengths.get(name)
            if max_len is None:
                continue
            try:
                # Only validate objects that have a length (e.g., strings, lists, dicts, etc.)
                val_len = len(value)
            except Exception:
                # If length can’t be determined, skip validation for this value.
                continue
            if val_len > max_len:
                raise ValueError(
                    f"Argument '{name}' length {val_len} exceeds maximum allowed {max_len}"
                )

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.

    :raises ValueError: If an argument value is not among the allowed choices.
    """
    for arg_name, arg_value in args.items():
        # Try to get the argument definition; its structure may vary
        arg_def = None
        if hasattr(self, "_arg_map"):
            arg_def = self._arg_map.get(arg_name)
        elif hasattr(self, "_cmd") and hasattr(self._cmd, "arg_map"):
            arg_def = self._cmd.arg_map.get(arg_name)

        # If there is no definition, skip validation for this arg
        if arg_def is None:
            continue

        # Attempt to extract the choices attribute; it may be a property or dict entry
        choices = None
        if isinstance(arg_def, dict):
            choices = arg_def.get("choices")
        else:
            choices = getattr(arg_def, "choices", None)

        # Skip if no choices are defined
        if choices is None:
            continue

        # Normalize choices to an iterable if it's a string (allowing commas)
        if not isinstance(choices, (list, tuple, set)):
            try:
                # Try converting to list if it's a comma-separated string
                if isinstance(choices, str):
                    choices = [c.strip() for c in choices.split(",")]
                else:
                    # Fallback: wrap the single choice in a list
                    choices = [choices]
            except Exception:
                # If conversion fails, treat as a single item list
                choices = [choices]

        # Validate the argument value is within the allowed choices
        if arg_value not in choices:
            raise ValueError(
                f'Invalid value "{arg_value}" for argument "{arg_name}". '
                f"Allowed choices are: {', '.join(map(str, choices))}."
            )

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Ensure the class has `min` and `max` attributes for validation.
    # If they are not set, do nothing.
    min_val = getattr(self, "min", None)
    max_val = getattr(self, "max", None)
    if min_val is None or max_val is None:
        return

    # Iterate over the provided arguments and validate each numeric value.
    for idx, value in enumerate(args):
        # Skip non-numeric values (or treat them as valid)
        if not isinstance(value, (int, float)):
            continue
        if value < min_val or value > max_val:
            raise ValueError(
                f"Argument at index {idx} with value {value!r} is outside the "
                f"allowed range [{min_val}, {max_val}]."
            )

def create_complex_argumet_type(self, subcommand, type_name, option_name, spec_option):
    """
    Build a simple complex argument type based on ``spec_option``.
    ``spec_option`` is expected to be a mapping of field names to either
    a type (int, float, str, bool) or a mapping ``{'type': <type>, 'default': <value>}``.
    The returned type is a plain ``object`` subclass with a custom ``__init__``,
    ``__repr__`` and documentation string that describes it.
    """
    # Map accepted type names to real types
    _type_map = {
        int: int,
        float: float,
        str: str,
        bool: bool,
    }

    # Resolve fields and defaults
    field_specs = {}
    for field, spec in spec_option.items():
        if isinstance(spec, dict):
            t = spec.get('type', str)
            dflt = spec.get('default', None)
        else:
            t = spec
            dflt = None
        # Convert string names to actual types if needed
        t = _type_map.get(t, t if isinstance(t, type) else str)
        field_specs[field] = (t, dflt)

    # Constructor: convert supplied values using the field type
    def __init__(self_local, **kwargs):
        for f_name, (f_type, f_default) in field_specs.items():
            raw_val = kwargs.get(f_name, f_default)
            if raw_val is not None:
                try:
                    if f_type is bool:
                        if isinstance(raw_val, str):
                            raw_val = raw_val.lower() in ('true', '1', 'yes')
                        else:
                            raw_val = bool(raw_val)
                    else:
                        raw_val = f_type(raw_val)
                except Exception as exc:
                    raise ValueError(f\"Invalid value for option '{option_name}': field '{f_name}'\") from exc
            setattr(self_local, f_name, raw_val)

    # Representation for debugging / testing
    def __repr__(self_local):
        parts = [f"{name}={getattr(self_local, name)!r}" for name in field_specs]
        return f"{type_name}({', '.join(parts)})"

    # Build the new type
    cls_dict = {
        "__init__": __init__,
        "__repr__": __repr__,
        "__module__": __name__,
        "__doc__": f"Complex argument type {type_name} for command '{subcommand}' option '{option_name}'.",
        "_fields": field_specs,
    }
    complex_type = type(type_name, (object,), cls_dict)

    return complex_type

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list/dict of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}

    # Determine the type of args and iterate accordingly.
    if isinstance(args, dict):
        items = args.items()
    else:
        try:
            # Assume iterable of (key, value) tuples.
            items = [(k, v) for k, v in args]
        except TypeError:
            # If it's a single key-value pair or unsupported type, treat as empty.
            items = []

    for key, val in items:
        if isinstance(key, str) and (key.startswith("control_") or key == "control"):
            control_args[key] = val
        else:
            # All other keys are considered nested/custom arguments.
            nested_args[key] = val

    return control_args, nested_args

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if extra_vars is None:
        return
    # If extra_vars is a dict, update directly
    if isinstance(extra_vars, dict):
        vars_dict.update(extra_vars)
    # If it's a list/tuple, iterate through elements
    elif isinstance(extra_vars, (list, tuple)):
        for ev in extra_vars:
            if isinstance(ev, dict):
                vars_dict.update(ev)
            elif isinstance(ev, str) and '=' in ev:
                k, v = ev.split('=', 1)
                vars_dict[k] = v
    # Handle a single string argument
    elif isinstance(extra_vars, str) and '=' in extra_vars:
        k, v = extra_vars.split('=', 1)
        vars_dict[k] = v
    return vars_dict

def _convert_non_cli_args(self, parser_name, values_dict):
        """
        Casts arguments to correct types by modifying values_dict param.

        By default all the values are strings.

        :param parser_name: The command name, e.g. main, virsh, ospd, etc
        :param values_dict: The dict of with arguments
       """
        # Helper to determine if a string looks like an integer.
        def _is_int(val):
            return isinstance(val, str) and val.isdigit()

        # Helper to determine if a string looks like a float.
        def _is_float(val):
            if not isinstance(val, str):
                return False
            try:
                float(val)
                return '.' in val or 'e' in val.lower()
            except ValueError:
                return False

        # Helper to determine if a string is a boolean value.
        def _is_bool(val):
            if not isinstance(val, str):
                return False
            return val.lower() in ('true', 'false', 'yes', 'no', '1', '0')

        # Helper to process a boolean string into a bool.
        def _bool_from_str(val):
            val_l = val.lower()
            if val_l in ('true', 'yes', '1'):
                return True
            if val_l in ('false', 'no', '0'):
                return False
            # fallback: treat non-empty strings as True
            return bool(val)

        # If values_dict is None or not a dict, nothing to do.
        if not isinstance(values_dict, dict):
            return

        for key, val in list(values_dict.items()):
            # Handle list values: comma-separated strings become list of elements
            if isinstance(val, str) and ',' in val:
                # Strip spaces around commas and ignore empty items
                parts = [item.strip() for item in val.split(',') if item.strip()]
                values_dict[key] = parts
                continue

            # Convert to integer if possible
            if _is_int(val):
                try:
                    values_dict[key] = int(val)
                    continue
                except Exception:
                    pass

            # Convert to float if possible
            if _is_float(val):
                try:
                    values_dict[key] = float(val)
                    continue
                except Exception:
                    pass

            # Convert to boolean if possible
            if _is_bool(val):
                try:
                    values_dict[key] = _bool_from_str(val)
                    continue
                except Exception:
                    pass

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
